#!/usr/bin/env bash
#
# A wizard walks a human, step by step, through a manual procedure.
# Generated by the /wizard skill.
#
# Objetivo: interceptar e DESCRIPTOGRAFAR o login da nuvem do app Tris Home
# (com.cz.czeye) para descobrir como o token é gerado/atualizado.
# Setup: celular Android ROOTADO + este PC Windows (Git Bash) via USB/adb.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5
ENV_FILE="captura.env"          # valores capturados ficam aqui (eu leio depois)
APP_PACKAGE="com.cz.czeye"      # pacote do Tris Home (confirmado no APK)
DUMP_FILE="login_nuvem.flows"   # dump do mitmproxy que vou analisar
PROXY_PORT="8080"

# Git Bash (MSYS) converte /data/... em C:\...\ antes do adb. Desliga só p/ adb.
adb() { MSYS_NO_PATHCONV=1 command adb "$@"; }
# Executáveis do pip podem cair na pasta Scripts do SISTEMA ou do USUÁRIO
# (no Windows o pip usa --user quando a do sistema não é gravável). Pegamos as duas.
SYS_SCRIPTS="$(cygpath -u "$(python -c 'import sysconfig;print(sysconfig.get_path("scripts"))' 2>/dev/null)" 2>/dev/null || true)"
USER_SCRIPTS="$(cygpath -u "$(python -c 'import sysconfig;print(sysconfig.get_path("scripts","nt_user"))' 2>/dev/null)" 2>/dev/null || true)"
for d in "$USER_SCRIPTS" "$SYS_SCRIPTS"; do [[ -n "$d" && -d "$d" ]] && PATH="$d:$PATH"; done
# SCRIPTS_DIR = pasta que realmente tem o mitmweb (pra mostrar ao usuário na etapa 4).
SCRIPTS_DIR="$USER_SCRIPTS"
{ [[ -x "$SYS_SCRIPTS/mitmweb" || -f "$SYS_SCRIPTS/mitmweb.exe" ]]; } && SCRIPTS_DIR="$SYS_SCRIPTS"
# android-unpinner é chamado como MÓDULO (não depende do .exe estar no PATH).
UNPIN="python -m android_unpinner"

banner "Captura SEM ROOT do login da nuvem - Tris Home ($APP_PACKAGE)"

# ── Stage 1: ferramentas no PC ────────────────────────────────────────────
stage "PC: instalar mitmproxy + android-unpinner"
say "Nada aqui mexe no celular ainda. Só preparamos o PC."
step "Instalando mitmproxy e android-unpinner (traz adb/apksigner/zipalign/gadget juntos)..."
python -m pip install --quiet --upgrade mitmproxy 2>&1 | tail -2 || warn "pip mitmproxy falhou"
python -m pip install --quiet --upgrade "git+https://github.com/mitmproxy/android-unpinner" 2>&1 | tail -2 \
  || warn "pip android-unpinner falhou (precisa de git no PATH; o Git Bash tem)."
if $UNPIN --help >/dev/null 2>&1; then
  say "android-unpinner OK (via '$UNPIN')."
else
  warn "android-unpinner não importou. Rode: python -m pip install --user git+https://github.com/mitmproxy/android-unpinner"
  pause "Instale e Enter (ou Ctrl-C)."
fi
command -v adb >/dev/null 2>&1 && say "adb (seu) OK: $(command -v adb)" || note "sem adb próprio; o android-unpinner traz o dele."
[[ -n "${SCRIPTS_DIR:-}" ]] && write_env SCRIPTS_DIR "$SCRIPTS_DIR"
write_env APP_PACKAGE "$APP_PACKAGE"
pause "Ferramentas prontas. Enter para continuar."

# ── Stage 2: conectar o celular (SEM root) ────────────────────────────────
stage "Celular: conectar via USB (não precisa de root)"
step "No celular: Ajustes → Sobre → toque 7x em 'Número da versão' (ativa Opções do desenvolvedor)."
step "Em Opções do desenvolvedor: ative 'Depuração USB'. Ligue o cabo USB."
step "Aceite o aviso 'Permitir depuração USB?' no celular."
pause "Feito? Enter para checar."
say "Dispositivos adb:"
adb devices
say "Modelo: $(adb shell getprop ro.product.model 2>/dev/null | tr -d '\r')  |  Android: $(adb shell getprop ro.build.version.release 2>/dev/null | tr -d '\r')"
if adb get-state 2>/dev/null | grep -q device; then
  say "Celular conectado e autorizado."
else
  warn "adb não vê o aparelho autorizado. Reconecte o cabo e aceite o aviso."
  pause "Ajuste e Enter (ou Ctrl-C)."
fi

# ── Stage 3: puxar os APKs do app (sem alterar nada ainda) ────────────────
stage "App: puxar os APKs do Tris Home (lida com splits)"
say "Aqui só BAIXAMOS os APKs do app pro PC. Nada é alterado no celular neste passo."
APK_DIR="apks_trishome"
step "Rodando: $UNPIN get-apks $APP_PACKAGE $APK_DIR"
if confirm "Puxar os APKs do $APP_PACKAGE para a pasta '$APK_DIR'?"; then
  rm -rf "$APK_DIR"
  $UNPIN get-apks "$APP_PACKAGE" "$APK_DIR" -f || warn "get-apks falhou; cole a saída que eu ajusto."
fi
if ls "$APK_DIR"/*.apk >/dev/null 2>&1; then
  say "APKs baixados em '$APK_DIR':"
  ls -1 "$APK_DIR"/*.apk | sed 's/^/    /'
  write_env APK_DIR "$APK_DIR"
else
  warn "Nenhum .apk em '$APK_DIR'. Verifique a saída do get-apks acima."
  pause "Ajuste e Enter (ou Ctrl-C)."
fi

# ── Stage 4: ligar o mitmproxy e rotear o celular (ANTES de abrir o app) ───
stage "Rede: ligar o mitmproxy e rotear o celular via USB"
say "O mitmproxy precisa estar NO AR antes de o app iniciar, pra capturar o login."
say "Usamos 'adb reverse' — o celular alcança o mitmproxy do PC pela própria USB."
step "ABRA OUTRO terminal Git Bash (nesta MESMA pasta) e deixe rodando:"
note "    mitmweb -w ${DUMP_FILE}      (interface em http://127.0.0.1:8081)"
[[ -n "${SCRIPTS_DIR:-}" ]] && note "    se der 'command not found', use o caminho completo:"
[[ -n "${SCRIPTS_DIR:-}" ]] && note "    \"${SCRIPTS_DIR}/mitmweb\" -w ${DUMP_FILE}"
pause "Deixe o mitmweb rodando no outro terminal e volte aqui. Enter."
step "Ligando o túnel USB e o proxy do celular:"
adb reverse "tcp:${PROXY_PORT}" "tcp:${PROXY_PORT}" && say "adb reverse tcp:${PROXY_PORT} → PC:${PROXY_PORT} OK"
adb shell settings put global http_proxy "127.0.0.1:${PROXY_PORT}" && say "Proxy do celular = 127.0.0.1:${PROXY_PORT}"
write_env MITM_ENDPOINT "127.0.0.1:${PROXY_PORT}"
write_env DUMP_FILE "$DUMP_FILE"
note "Para desfazer depois: adb shell settings put global http_proxy :0 ; adb reverse --remove-all"

# ── Stage 5: patch + instalar + iniciar o app, e capturar o login ─────────
stage "App: injetar o gadget, reinstalar, abrir e fazer login (só o Tris Home)"
warn "Agora o '$UNPIN all' vai: re-assinar, (des)instalar e INICIAR só o $APP_PACKAGE."
warn "Não toca em outros apps nem nos seus dados. Você fará login no app de novo."
step "Comando: $UNPIN all -f $APK_DIR/*.apk"
if confirm "Patchar, instalar e iniciar o Tris Home com o gadget agora?"; then
  $UNPIN all -f "$APK_DIR"/*.apk || warn "android-unpinner all falhou; cole aqui a saída que eu ajusto."
fi
say ""
say "O app foi aberto JÁ com o gadget + unpinning ativos (e o mitmproxy capturando)."
step "No celular: SAIA da conta (logout) e FAÇA LOGIN de novo."
step "Depois abra UMA câmera ao vivo por alguns segundos."
say "Isso força a geração de tokens novos — devem aparecer DESCRIPTOGRAFADOS no mitmweb."
note "Se o app foi fechado, reabra COM gadget: $UNPIN start-app $APP_PACKAGE"
say ""
step "No mitmweb (http://127.0.0.1:8081) confira se aparecem estes hosts, com conteúdo legível:"
note "    *.jftechws.com · icsee.boss.jftech.com · *.secu100.net · *.xmeye.net"
pause "Fez login + viu os fluxos? Pare o mitmweb (Ctrl-C no outro terminal) e volte. Enter."
if confirm "Apareceu tráfego HTTPS LEGÍVEL desses hosts (não só 'CONNECT' / handshake falho)?"; then
  say "Isso! O arquivo '${DUMP_FILE}' tem o login descriptografado — me avise que eu analiso."
else
  warn "Se só veio 'CONNECT'/'handshake failed': o login crítico é TLS NATIVO (FunSDK) que ignora o proxy."
  note "Sem root não há iptables pra redirecionar o tráfego nativo; aí o próximo passo é hook nativo do BoringSSL."
  note "Em qualquer caso, me diga o que apareceu no mitmweb que eu avalio."
fi

finish
